Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Notation SEGS := asegs (only parsing).
Local Ltac xms H := first [exact H | apply msteps_bridge; exact H].

Definition PC_FW2 : Z := 0x16f06c.
Definition PC_RET_FW2 : Z := 0x16f070.
Definition PC_FW3 : Z := 0x16f194.
Definition PC_RET_FW3 : Z := 0x16f198.
Definition PC_MS : Z := 0x16f124.
Definition PC_RET_MS : Z := 0x16f128.
Definition PC_FWP : Z := 0x16f178.
Definition PC_RET_FWP : Z := 0x16f17c.

Section Pass2C.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Variables (F : bvmap 5 word) (fc : bv 32).
  Variable gd : Z.
  Hypothesis Hgd : 0 <= gd < 2 ^ 64.
  Variables (R : bvmap 5 word) (M : mem) (sp ret v conv lo shi : Z).

  Hypothesis Hra : getr R 1%bv = Z_to_bv 64 ret.
  Hypothesis Hret : ret_ok (Z_to_bv 64 ret).
  Hypothesis Hretr : 0 <= ret < 2 ^ 64.
  Hypothesis Hsp : getr R 2%bv = Z_to_bv 64 sp.
  Hypothesis Ha0 : getr R 10%bv = Z_to_bv 64 (sp + 416).
  Hypothesis Ha1 : getr R 11%bv = Z_to_bv 64 (sp + 3056).
  Hypothesis Ha2 : getr R 12%bv = Z_to_bv 64 sp.
  Hypothesis Ha3 : getr R 13%bv = Z_to_bv 64 (sp + 96).
  Hypothesis Ha4 : getr R 14%bv = Z_to_bv 64 (sp + 264).
  Hypothesis Hsplo : 2 ^ 32 <= sp - 608.
  Hypothesis Hsphi : sp + 3060 < 2 ^ 47.
  Hypothesis Hal : sp mod 16 = 0.
  Hypothesis HD : mdef M (sp - 608) 3668.
  Hypothesis Fap : fld SEGS M sp 8 (sp + 2928).
  Hypothesis Fv : fld SEGS M (sp + 2928) 8 v.
  Hypothesis Hv : 0 <= v < 2 ^ 64.
  Hypothesis F0 : fld SEGS M (sp + 3056) 1 37.
  Hypothesis F1 : fld SEGS M (sp + 3057) 1 108.
  Hypothesis F2 : fld SEGS M (sp + 3058) 1 conv.
  Hypothesis F3 : fld SEGS M (sp + 3059) 1 0.
  Hypothesis Hconv : conv = 117 \/ conv = 100 \/ conv = 120.
  Hypothesis Fflags : fld SEGS M (sp + 416) 4 0.
  Hypothesis Fwend : fld SEGS M (sp + 416 + 32) 8 (sp + 96).
  Hypothesis Fwpos : fld SEGS M (sp + 416 + 40) 8 (sp + 16).
  Hypothesis Flbf : fld SEGS M (sp + 416 + 144) 4 (2 ^ 32 - 1).
  Hypothesis ROC : mem_inv asegs M.
  Hypothesis RRC : relro_clear M.
  Hypothesis FCAN : fld SEGS M A_CANARY 8 gd.

  Hypothesis RF : rfull R.
  Hypothesis NI : ninv lo shi M.
  Hypothesis STK : stk asegs M lo sp.
  Hypothesis CEIL : aceil <= lo.
  Hypothesis LOS : lo + AINTRIN_STACK + 64 + 608 <= sp.
  Hypothesis SHI : sp + 3060 + 64 <= shi.
  Hypothesis Hre : ret mod 2 = 0.
  Hypothesis Hr48 : ret < 2 ^ 48.

  Let pcs := sp - 544.
  Hypothesis Hvpos : conv = 100 -> v < 2 ^ 63.

  #[local] Abbreviation pcframe := (pcframe gd R sp ret).
  #[local] Abbreviation ffile := (ffile sp).
  #[local] Abbreviation stC := (stC gd R M sp ret v conv).
  #[local] Abbreviation pcconst := (pcconst sp).

  Definition pass2_post (nc : Z) (R' : bvmap 5 word) (M' : mem) : Prop :=
    getr R' 10%bv = Z_to_bv 64 nc /\ 1 <= nc <= 21
    /\ (forall r, In r leaf_kept -> getr R' r = getr R r)
    /\ stores_in (fun a => zwin (sp - 608 - AINTRIN_STACK) (sp + 96) a \/ zwin (sp + 416 + 40) (sp + 416 + 48) a) M M'
    /\ fld SEGS M' (sp + 416 + 40) 8 (sp + 16 + nc)
    /\ rfull R' /\ ninv lo shi M'.

  Lemma tail_pos : forall R3 M3 m nd pl, stC R3 M3 m nd pl -> 0 < m -> rfull R3 -> ninv lo shi M3 -> stk asegs M3 lo pcs ->
